"""Execute and judge code generated by the Qwen Pixel SFT adapter."""
import argparse
import base64
import json
import re
import sys
from pathlib import Path

from openai import AzureOpenAI

ROOT = Path('/mnt/bn/embodied-lf3/masiyuan')
sys.path.insert(0, str(ROOT / 'qwen_pixel/scripts'))
from build_teacher_magicbrush import metrics, run_code  # noqa: E402

PROMPT = '''You are evaluating an image editing result.
Image 1: source image.
Image 2: reference target image (may differ in layout/scan; use as guidance, not pixel alignment).
Image 3: model prediction.
Instruction: {instruction}
Score 1-5 for instruction_adherence, preservation, visual_quality, and set pass true only if the edit is clearly correct and usable.
Return JSON only: {{"instruction_adherence":1,"preservation":1,"visual_quality":1,"pass":false,"reason":"..."}}
'''


def b64(path):
    return base64.b64encode(Path(path).read_bytes()).decode()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--generations', required=True)
    parser.add_argument('--samples', required=True)
    parser.add_argument('--out', required=True)
    args = parser.parse_args()
    generations = [json.loads(l) for l in Path(args.generations).read_text().splitlines() if l.strip()]
    samples = {r['id']: r for r in [json.loads(l) for l in Path(args.samples).read_text().splitlines() if l.strip()]}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    (out / 'executions').mkdir(exist_ok=True)
    client = AzureOpenAI(api_key=__import__("os").environ["QWEN_PIXEL_PROXY_KEY"],
                         api_version='2023-07-01-preview',
                         azure_endpoint='https://search.bytedance.net/gpt/openapi/online/multimodal/crawl',
                         timeout=240)
    results = []
    for gen in generations:
        cid = gen['id']
        sample = samples.get(cid)
        text = gen['text']
        match = re.search(r'<code>(.*?)</code>', text, re.S)
        code = match.group(1).strip() if match else ''
        result = {'id': cid, 'instruction': sample['instruction'] if sample else '',
                  'code_present': bool(match), 'code_length': len(code)}
        if not sample or not match:
            result.update(execution='skipped', pass_=False)
            results.append(result)
            continue
        execution = run_code(code, Path(sample['source_image']),
                             out / 'executions' / f'{cid}.png')
        result['execution'] = execution['status']
        result['error'] = execution.get('error', '')
        if execution['status'] == 'passed':
            result['metrics'] = metrics(Path(sample['source_image']), Path(sample['target_image']),
                                        out / 'executions' / f'{cid}.png', Path(sample['mask_image']))
            content = [
                {'type': 'text', 'text': PROMPT.format(instruction=sample['instruction'])},
                {'type': 'image_url', 'image_url': {'url': 'data:image/png;base64,' + b64(sample['source_image'])}},
                {'type': 'image_url', 'image_url': {'url': 'data:image/png;base64,' + b64(sample['target_image'])}},
                {'type': 'image_url', 'image_url': {'url': 'data:image/png;base64,' + b64(out / 'executions' / f'{cid}.png')}},
            ]
            response = client.chat.completions.create(
                model='gpt-5.5-2026-04-24', messages=[{'role': 'user', 'content': content}],
                max_completion_tokens=8192, reasoning_effort='low')
            judge_text = (response.choices[0].message.content or '').strip()
            judge_text = re.sub(r'^```(?:json)?\s*', '', judge_text)
            judge_text = re.sub(r'\s*```$', '', judge_text)
            try:
                judge = json.loads(judge_text)
            except Exception:
                judge = {'raw': judge_text}
            result['judge'] = judge
        results.append(result)
        print(json.dumps(result, ensure_ascii=False), flush=True)
    (out / 'results.jsonl').write_text(''.join(json.dumps(r, ensure_ascii=False) + '\n' for r in results))
    passed = sum(1 for r in results if r.get('judge', {}).get('pass'))
    summary = {'total': len(results), 'executed': sum(1 for r in results if r.get('execution') == 'passed'),
               'judge_pass': passed, 'pass_rate': passed / len(results) if results else 0}
    (out / 'summary.json').write_text(json.dumps(summary, indent=2))
    print(json.dumps(summary, indent=2))


if __name__ == '__main__':
    main()
